import type { ReactElement, ReactNode } from 'react'
import { Popover as BasePopover } from '@base-ui/react/popover'
import { Icon } from '@/lib/icon'
import { cn } from '@/lib/utils'
import styles from './Popover.module.css'

export interface PopoverProps {
  /** The element that opens it: one button. Its props are merged, not wrapped. */
  trigger: ReactElement
  /** Names the popover (it is a dialog). Without one, pass `aria-label`. */
  title?: ReactNode
  description?: ReactNode
  children?: ReactNode
  side?: 'top' | 'right' | 'bottom' | 'left'
  align?: 'start' | 'center' | 'end'
  hasArrow?: boolean
  /** A close button in the corner. Escape and a click outside close it either way. */
  hasCloseButton?: boolean
  closeLabel?: string
  /** Open on hover as well as click, for previews. Content must still be reachable by click and keyboard. */
  openOnHover?: boolean
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  /** Trap focus inside while open, lock page scroll and block clicks outside (Base UI's modal mode). */
  isModal?: boolean
  'aria-label'?: string
  className?: string
}

export function Popover({
  trigger,
  title,
  description,
  children,
  side = 'bottom',
  align = 'center',
  hasArrow = false,
  hasCloseButton = false,
  closeLabel = 'Close',
  openOnHover = false,
  open,
  defaultOpen,
  onOpenChange,
  isModal = false,
  'aria-label': ariaLabel,
  className,
}: PopoverProps) {
  return (
    <BasePopover.Root
      open={open}
      defaultOpen={defaultOpen}
      onOpenChange={onOpenChange && ((next) => onOpenChange(next))}
      modal={isModal}
    >
      <BasePopover.Trigger render={trigger} openOnHover={openOnHover} />
      <BasePopover.Portal>
        <BasePopover.Positioner className={styles.positioner} side={side} align={align} sideOffset={hasArrow ? 10 : 6}>
          <BasePopover.Popup aria-label={title ? undefined : ariaLabel} className={cn(styles.popup, className)}>
            {hasArrow && <BasePopover.Arrow className={styles.arrow} />}
            {(title || hasCloseButton) && (
              <div className={styles.header}>
                {title && <BasePopover.Title className={styles.title}>{title}</BasePopover.Title>}
                {hasCloseButton && (
                  <BasePopover.Close aria-label={closeLabel} className={styles.close}>
                    <Icon name="close" />
                  </BasePopover.Close>
                )}
              </div>
            )}
            {/* Base UI only traps focus in a modal popover that contains a
                Close, and a touch screen reader needs one to get out. */}
            {isModal && !hasCloseButton && (
              <BasePopover.Close aria-label={closeLabel} className={cn(styles.close, styles.hiddenClose)}>
                <Icon name="close" />
              </BasePopover.Close>
            )}
            {description && <BasePopover.Description className={styles.description}>{description}</BasePopover.Description>}
            {children && <div className={styles.body}>{children}</div>}
          </BasePopover.Popup>
        </BasePopover.Positioner>
      </BasePopover.Portal>
    </BasePopover.Root>
  )
}

/* 50: the popup layer, shared with Select and Combobox. Tooltips sit
   above at 60. */
.positioner {
  z-index: 50;
}

.popup {
  box-sizing: border-box;
  inline-size: max-content;
  max-inline-size: min(22rem, var(--available-width));
  padding: var(--space-4);
  border: 1px solid var(--border);
  border-radius: var(--radius-panel);
  background: var(--popover);
  box-shadow: var(--shadow-md);
  color: var(--popover-foreground);
  font-family: var(--font-sans);
  font-size: var(--text-body);
  line-height: var(--leading-body);
  outline: none;
  transform-origin: var(--transform-origin);
  transition:
    opacity 120ms,
    scale 120ms;
}

.popup[data-starting-style],
.popup[data-ending-style] {
  opacity: 0;
  scale: 0.97;
}

.header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--space-3);
}

.title {
  margin: 0;
  font-size: var(--text-body);
  line-height: var(--leading-body);
  font-weight: 600;
}

.description {
  margin: var(--space-1) 0 0;
  color: var(--muted-foreground);
}

.header + .body,
.description + .body {
  margin-block-start: var(--space-3);
}

/* A 10px square turned 45deg: half pokes out, the border on two edges
   continues the popup's. */
.arrow {
  inline-size: 10px;
  block-size: 10px;
  background: var(--popover);
  rotate: 45deg;
}
.arrow[data-side='bottom'] {
  top: -6px;
  border-block-start: 1px solid var(--border);
  border-inline-start: 1px solid var(--border);
}
.arrow[data-side='top'] {
  bottom: -6px;
  border-block-end: 1px solid var(--border);
  border-inline-end: 1px solid var(--border);
}
.arrow[data-side='right'] {
  left: -6px;
  border-block-end: 1px solid var(--border);
  border-inline-start: 1px solid var(--border);
}
.arrow[data-side='left'] {
  right: -6px;
  border-block-start: 1px solid var(--border);
  border-inline-end: 1px solid var(--border);
}

.close {
  position: relative;
  display: inline-flex;
  flex-shrink: 0;
  margin: calc(var(--space-1) * -1) calc(var(--space-1) * -1) 0 auto;
  /* 2px around a 16px icon: a 20px button, one line of text tall. */
  padding: 2px;
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--muted-foreground);
  font-size: var(--space-4);
  cursor: var(--cursor-button);
}
.close:hover {
  background: var(--accent);
  color: var(--accent-foreground);
}
.close:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 1px;
}
@media (pointer: coarse) {
  .close::before {
    content: '';
    position: absolute;
    inset: 50% auto auto 50%;
    inline-size: 44px;
    block-size: 44px;
    translate: -50% -50%;
  }
}

/* The modal's close button when none is shown: out of sight until it
   has keyboard focus, then in the corner like a skip link, so focus is
   never invisible. */
.hiddenClose {
  position: absolute;
  inset-block-start: var(--space-2);
  inset-inline-end: var(--space-2);
  margin: 0;
}
.hiddenClose:not(:focus-visible) {
  inline-size: 1px;
  block-size: 1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
}

@media (prefers-reduced-motion: reduce) {
  .popup {
    transition: none;
  }
}
